Customer Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(customer_portal, "Customer Portal") {
    Component(Claim Submission Controller, "Claim Submission Controller", "Next.js API Route / TypeScript", "Handles incoming online claim submissions and validation from customers and brokers.")
    Component(Broker Dashboard Service, "Broker Dashboard Service", "React / TypeScript", "Provides customer-facing interactions, submission tracking, and broker dashboards.")
    Component(Authentication Client, "Authentication Client", "NextAuth.js", "Manages OpenID Connect / OAuth 2.0 authentication flow with Azure AD.")
}

Rel(Claim Submission Controller, Broker Dashboard Service, "Updates UI state")
Rel(Authentication Client, Claim Submission Controller, "Provides security context")
@enduml

Integration Gateway / ACL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(integration_gateway, "Integration Gateway / ACL") {
    Component(Message_Translator, "Message Translator", "Azure Container Apps / .NET Core", "Translates modern JSON/REST messages into legacy COBOL copybook formats for mainframe consumption.")
    Component(Mainframe_Adapter, "Mainframe Adapter", "Azure Container Apps / ESB Client", "Manages secure, hybrid ESB/MQ connections with the on-premise Legacy Mainframe.")
}

Rel(Message_Translator, Mainframe_Adapter, "Forwards translated legacy messages")

@enduml

Feature Flag / Migration Router.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Feature_Flag_Migration_Router", "Feature Flag / Migration Router") {
    Component(Router_Controller, "Router Controller", "Azure Container Apps / ASP.NET Core", "Handles incoming routing requests and evaluates migration paths for claims.")
    Component(Feature_Flag_Evaluator, "Feature Flag Evaluator", "Azure App Configuration SDK", "Queries feature flags and rules to determine legacy vs modern processing.")
}

Rel(Router_Controller, Feature_Flag_Evaluator, "Evaluates flags", "")
@enduml
